00042 namespace vtm {
00043 
00044 void calculateParameterSetChangedFlag(bool &bChanged, const std::vector<uint8_t> *pOldData, const std::vector<uint8_t> *pNewData);
00045 
00046 template <class T> class ParameterSetMap
00047 {
00048 public:
00049   template <class Tm>
00050   struct MapData
00051   {
00052     bool                  bChanged;
00053     std::vector<uint8_t>   *pNaluData; // Can be null
00054     Tm*                   parameterSet;
00055   };
00056 
00057   ParameterSetMap(int maxId)
00058   :m_maxId (maxId)
00059   ,m_lastActiveParameterSet(NULL)
00060   {
00061     m_activePsId.clear();
00062   }
00063 
00064   ~ParameterSetMap()
00065   {
00066     for (typename std::map<int,MapData<T> >::iterator i = m_paramsetMap.begin(); i!= m_paramsetMap.end(); i++)
00067     {
00068       delete (*i).second.pNaluData;
00069       delete (*i).second.parameterSet;
00070     }
00071     delete m_lastActiveParameterSet; m_lastActiveParameterSet = NULL;
00072   }
00073 
00074   T *allocatePS(const int psId)
00075   {
00076     CHECK( psId >= m_maxId, "Invalid PS id" );
00077     if ( m_paramsetMap.find(psId) == m_paramsetMap.end() )
00078     {
00079       m_paramsetMap[psId].bChanged = true;
00080       m_paramsetMap[psId].pNaluData=0;
00081       m_paramsetMap[psId].parameterSet = new T;
00082       setID(m_paramsetMap[psId].parameterSet, psId);
00083     }
00084     return m_paramsetMap[psId].parameterSet;
00085   }
00086 
00087   void clearMap()
00088   {
00089     m_paramsetMap.clear();
00090   }
00091   void storePS( int psId, T *ps )
00092   {
00093     CHECK( psId >= m_maxId, "Invalid PS id" );
00094     if( m_paramsetMap.find( psId ) != m_paramsetMap.end() )
00095     {
00096       delete m_paramsetMap[psId].parameterSet;
00097     }
00098     m_paramsetMap[psId].parameterSet = ps;
00099     m_paramsetMap[psId].bChanged = true;
00100   }
00101   void storePS(int psId, T *ps, const std::vector<uint8_t> *pNaluData)
00102   {
00103     CHECK( psId >= m_maxId, "Invalid PS id" );
00104     if ( m_paramsetMap.find(psId) != m_paramsetMap.end() )
00105     {
00106       MapData<T> &mapData=m_paramsetMap[psId];
00107 
00108       // work out changed flag
00109       calculateParameterSetChangedFlag(mapData.bChanged, mapData.pNaluData, pNaluData);
00110 
00111       if( ! mapData.bChanged )
00112       {
00113         // just keep the old one
00114         delete ps;
00115         return;
00116       }
00117 
00118       if (find(m_activePsId.begin(), m_activePsId.end(), psId) != m_activePsId.end())
00119       {
00120         std::swap( m_paramsetMap[psId].parameterSet, m_lastActiveParameterSet );
00121       }
00122       delete m_paramsetMap[psId].pNaluData;
00123       delete m_paramsetMap[psId].parameterSet;
00124 
00125       m_paramsetMap[psId].parameterSet = ps;
00126     }
00127     else
00128     {
00129       m_paramsetMap[psId].parameterSet = ps;
00130       m_paramsetMap[psId].bChanged = false;
00131     }
00132     if (pNaluData != 0)
00133     {
00134       m_paramsetMap[psId].pNaluData=new std::vector<uint8_t>;
00135       *(m_paramsetMap[psId].pNaluData) = *pNaluData;
00136     }
00137     else
00138     {
00139       m_paramsetMap[psId].pNaluData=0;
00140     }
00141   }
00142 
00143   void checkAuApsContent( APS *aps, std::vector<int>& accessUnitApsNals )
00144   {
00145     int apsId = ( aps->getAPSId() << NUM_APS_TYPE_LEN ) + aps->getAPSType();
00146 
00147     if( std::find( accessUnitApsNals.begin(), accessUnitApsNals.end(), apsId ) != accessUnitApsNals.end() )
00148     {
00149       CHECK( m_paramsetMap.find( apsId ) == m_paramsetMap.end(), "APS does not exist" );
00150       APS* existedAPS = m_paramsetMap[apsId].parameterSet;
00151       bool sameNalUnitType = aps->getHasPrefixNalUnitType() == existedAPS->getHasPrefixNalUnitType();
00152       bool samePU = aps->getLayerId() == existedAPS->getLayerId();
00153       if( aps->getAPSType() == LMCS_APS )
00154       {
00155         CHECK( samePU && sameNalUnitType && aps->getReshaperAPSInfo() != existedAPS->getReshaperAPSInfo(), "All APS NAL units with a particular value of nal_unit_type, a particular value of aps_adaptation_parameter_set_id, and a particular value of aps_params_type within a PU shall have the same content" );
00156       }
00157       else if( aps->getAPSType() == ALF_APS )
00158       {
00159         CHECK( samePU && sameNalUnitType && aps->getAlfAPSParam() != existedAPS->getAlfAPSParam(), "All APS NAL units with a particular value of nal_unit_type, a particular value of aps_adaptation_parameter_set_id, and a particular value of aps_params_type within a PU shall have the same content" );
00160       }
00161       else if( aps->getAPSType() == SCALING_LIST_APS )
00162       {
00163         CHECK( samePU && sameNalUnitType && aps->getScalingList() != existedAPS->getScalingList(), "All APS NAL units with a particular value of nal_unit_type, a particular value of aps_adaptation_parameter_set_id, and a particular value of aps_params_type within a PU shall have the same content" );
00164       }
00165       else
00166       {
00167         CHECK( true, "Wrong APS type" );
00168       }
00169     }
00170     else
00171     {
00172       accessUnitApsNals.push_back( apsId );
00173     }
00174   }
00175 
00176 
00177   void setChangedFlag(int psId, bool bChanged=true)
00178   {
00179     if ( m_paramsetMap.find(psId) != m_paramsetMap.end() )
00180     {
00181       m_paramsetMap[psId].bChanged=bChanged;
00182     }
00183   }
00184 
00185   void clearChangedFlag(int psId)
00186   {
00187     if ( m_paramsetMap.find(psId) != m_paramsetMap.end() )
00188     {
00189       m_paramsetMap[psId].bChanged=false;
00190     }
00191   }
00192 
00193   bool getChangedFlag(int psId) const
00194   {
00195     const typename std::map<int,MapData<T> >::const_iterator constit=m_paramsetMap.find(psId);
00196     if ( constit != m_paramsetMap.end() )
00197     {
00198       return constit->second.bChanged;
00199     }
00200     return false;
00201   }
00202 
00203   T* getPS(int psId)
00204   {
00205     typename std::map<int,MapData<T> >::iterator it=m_paramsetMap.find(psId);
00206     return ( it == m_paramsetMap.end() ) ? NULL : (it)->second.parameterSet;
00207   }
00208 
00209   const T* getPS(int psId) const
00210   {
00211     typename std::map<int,MapData<T> >::const_iterator it=m_paramsetMap.find(psId);
00212     return ( it == m_paramsetMap.end() ) ? NULL : (it)->second.parameterSet;
00213   }
00214 
00215   T* getFirstPS()
00216   {
00217     return (m_paramsetMap.begin() == m_paramsetMap.end() ) ? NULL : m_paramsetMap.begin()->second.parameterSet;
00218   }
00219 
00220   void setActive(int psId) { m_activePsId.push_back(psId); }
00221   void clearActive() { m_activePsId.clear(); }
00222 
00223 private:
00224   std::map<int,MapData<T> > m_paramsetMap;
00225   int                       m_maxId;
00226   std::vector<int>          m_activePsId;
00227   T*                        m_lastActiveParameterSet;
00228   static void setID(T* parameterSet, const int psId);
00229 };
00230 
00231 class ParameterSetManager
00232 {
00233 public:
00234                  ParameterSetManager();
00235   virtual        ~ParameterSetManager();
00236 
00237   // store video parameter set and take ownership of it
00238   // warning: vps object cannot be used after storing (repeated parameter sets are directly deleted)
00239   void           storeVPS(VPS *vps, const std::vector<uint8_t> &naluData)    { m_vpsMap.storePS(vps->getVPSId(), vps, &naluData); }
00240   VPS*           getVPS( int vpsId );
00241 
00242   // store sequence parameter set and take ownership of it
00243   // warning: sps object cannot be used after storing (repeated parameter sets are directly deleted)
00244   void           storeSPS(SPS *sps, const std::vector<uint8_t> &naluData)    { m_spsMap.storePS( sps->getSPSId(), sps, &naluData); };
00245   // get pointer to existing sequence parameter set
00246   SPS*           getSPS(int spsId)                                           { return m_spsMap.getPS(spsId); };
00247   bool           getSPSChangedFlag(int spsId) const                          { return m_spsMap.getChangedFlag(spsId); }
00248   void           clearSPSChangedFlag(int spsId)                              { m_spsMap.clearChangedFlag(spsId); }
00249   SPS*           getFirstSPS()                                               { return m_spsMap.getFirstPS(); };
00250 
00251   // store picture parameter set and take ownership of it
00252   // warning: pps object cannot be used after storing (repeated parameter sets are directly deleted)
00253   void           storePPS(PPS *pps, const std::vector<uint8_t> &naluData)    { m_ppsMap.storePS( pps->getPPSId(), pps, &naluData); };
00254   // get pointer to existing picture parameter set
00255   PPS*           getPPS(int ppsId)                                           { return m_ppsMap.getPS(ppsId); };
00256   bool           getPPSChangedFlag(int ppsId) const                          { return m_ppsMap.getChangedFlag(ppsId); }
00257   void           clearPPSChangedFlag(int ppsId)                              { m_ppsMap.clearChangedFlag(ppsId); }
00258   PPS*           getFirstPPS()                                               { return m_ppsMap.getFirstPS(); };
00259 
00260   // activate a PPS and depending on isIRAP parameter also SPS
00261   // returns true, if activation is successful
00262   bool           activatePPS(int ppsId, bool isIRAP);
00263 
00264   APS**          getAPSs() { return &m_apss[0]; }
00265   ParameterSetMap<APS>* getApsMap() { return &m_apsMap; }
00266   // store adaptation parameter set and take ownership of it
00267   // warning: aps object cannot be used after storing (repeated parameter sets are directly deleted)
00268   void           storeAPS(APS *aps, const std::vector<uint8_t> &naluData)    { m_apsMap.storePS( ( aps->getAPSId() << NUM_APS_TYPE_LEN ) + aps->getAPSType(), aps, &naluData); };
00269   APS*           getAPS(int apsId, int apsType)                              { return m_apsMap.getPS( ( apsId << NUM_APS_TYPE_LEN ) + apsType ); };
00270   bool           getAPSChangedFlag(int apsId, int apsType) const             { return m_apsMap.getChangedFlag( ( apsId << NUM_APS_TYPE_LEN ) + apsType ); }
00271   void           clearAPSChangedFlag(int apsId, int apsType)                 { m_apsMap.clearChangedFlag( ( apsId << NUM_APS_TYPE_LEN ) + apsType ); }
00272   APS*           getFirstAPS()                                               { return m_apsMap.getFirstPS(); };
00273   bool           activateAPS(int apsId, int apsType);
00274   const SPS*     getActiveSPS()const                                         { return m_spsMap.getPS(m_activeSPSId); };
00275   void           checkAuApsContent( APS *aps, std::vector<int>& accessUnitApsNals ) { m_apsMap.checkAuApsContent( aps, accessUnitApsNals ); }
00276 
00277 protected:
00278   ParameterSetMap<SPS> m_spsMap;
00279   ParameterSetMap<PPS> m_ppsMap;
00280   ParameterSetMap<APS> m_apsMap;
00281   ParameterSetMap<VPS> m_vpsMap;
00282 
00283   APS* m_apss[ALF_CTB_MAX_NUM_APS];
00284   int m_activeSPSId; // -1 for nothing active
00285   int m_activeVPSId; // -1 for nothing active
00286 };
00287 
00288 } // namespace vtm
